const imgProduct = "https://www.figma.com/api/mcp/asset/fa10fe7e-d4ac-4f36-83eb-7fa678a107b7.png";

type LinkProps = {
  className?: string;
  label?: string;
  size?: "Large";
  state?: "default";
};

function Link({ className, label = "Label", size = "Large", state = "default" }: LinkProps) {
  return (
    <div className={className || "content-stretch flex flex-col h-[24px] items-start justify-center py-[var(--alias\\/space\\/100,4px)] relative"} data-node-id="40000138:469">
      <p className="[text-box-edge:cap_alphabetic] [text-box-trim:trim-both] [text-underline-position:from-font] [word-break:break-word] decoration-from-font decoration-solid font-[family-name:var(--brand\/font\/family\/body,'Futura_Round:medium')] font-[var(--brand\/font\/weight\/bold,normal)] leading-[var(--line-height\/caption,18px)] relative shrink-0 text-[color:var(--alias\/color\/link\/default,#191919)] text-[length:var(--brand\/font\/size\/350,14px)] tracking-[var(--brand\/font\/letterspacing\/negative-100,-0.12px)] underline uppercase whitespace-nowrap" data-node-id="2262:64028">
        {label}
      </p>
    </div>
  );
}

type RecentlyViewedProps = {
  className?: string;
  showTitleAndLink?: boolean;
  size?: "Tablet";
};

function RecentlyViewed({ className, showTitleAndLink = true, size = "Tablet" }: RecentlyViewedProps) {
  return (
    <div className={className || "content-stretch flex flex-col items-start max-w-[1023px] min-w-[768px] relative w-[768px]"} data-node-id="40000730:13363">
      {showTitleAndLink && (
        <div className="content-stretch flex items-center pb-[var(--alias\/space\/300,12px)] pt-[var(--alias\/space\/500,20px)] px-[var(--alias\/space\/800,32px)] relative shrink-0 w-full" data-node-id="40000730:13364" data-name="title-and-link">
          <div className="content-stretch flex flex-[1_0_0] gap-[var(--alias\/space\/800,32px)] items-center min-w-px relative" data-node-id="I40000730:13364;40000730:13406" data-name="Content">
            <div className="[text-box-edge:cap_alphabetic] [text-box-trim:trim-both] [word-break:break-word] flex flex-[1_0_0] flex-col font-[family-name:var(--brand\/font\/family\/heading,'Futura_Round:medium')] font-[var(--brand\/font\/weight\/bold,normal)] h-[16px] justify-center leading-[0] min-w-px relative text-[color:var(--alias\/color\/text\/default,#191919)] text-[length:var(--brand\/font\/size\/400,16px)] tracking-[var(--brand\/font\/letterspacing\/negative-100,-0.12px)] uppercase" data-node-id="I40000730:13364;40000730:13407">
              <p className="leading-[var(--line-height\/heading-3-medium,18px)]">Enter your title here</p>
            </div>
            <Link className="content-stretch flex flex-col h-[24px] items-start justify-center py-[var(--alias\/space\/100,4px)] relative shrink-0" />
          </div>
        </div>
      )}
